def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can be transformed into t in at most k edits.

    An insertion, deletion, or replacement each costs one operation.
    """
    if k < 0:
        return False
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False

    # Common ends do not affect the edit distance and can shrink the DP band.
    start = 0
    limit = min(n, m)
    while start < limit and s[start] == t[start]:
        start += 1

    end_s, end_t = n, m
    while end_s > start and end_t > start and s[end_s - 1] == t[end_t - 1]:
        end_s -= 1
        end_t -= 1

    a, b = s[start:end_s], t[start:end_t]
    n, m = len(a), len(b)
    if abs(n - m) > k:
        return False
    if not n:
        return m <= k
    if not m:
        return n <= k

    # prev stores the previous row only for columns in its active band.
    prev_lo = 0
    prev_hi = min(m, k)
    prev = list(range(prev_hi + 1))
    infinity = k + 1

    for i in range(1, n + 1):
        lo = max(0, i - k)
        hi = min(m, i + k)
        curr = [infinity] * (hi - lo + 1)
        row_min = infinity

        for j in range(lo, hi + 1):
            if j == 0:
                value = i
            else:
                deletion = (prev[j - prev_lo] + 1
                            if prev_lo <= j <= prev_hi else infinity)
                insertion = (curr[j - 1 - lo] + 1
                             if j - 1 >= lo else infinity)
                replacement = (prev[j - 1 - prev_lo] + (a[i - 1] != b[j - 1])
                               if prev_lo <= j - 1 <= prev_hi else infinity)
                value = min(deletion, insertion, replacement)
            if value > infinity:
                value = infinity
            curr[j - lo] = value
            if value < row_min:
                row_min = value

        if row_min > k:
            return False
        prev, prev_lo, prev_hi = curr, lo, hi

    return prev[m - prev_lo] <= k

