def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count simple paths of exactly K moves, with every empty cell as a start."""
    n = H * W
    neighbors = [[] for _ in range(n)]
    for r in range(H):
        for c in range(W):
            i = r * W + c
            if grid[r][c] != ".":
                continue
            if r:
                neighbors[i].append(i - W)
            if r + 1 < H:
                neighbors[i].append(i + W)
            if c:
                neighbors[i].append(i - 1)
            if c + 1 < W:
                neighbors[i].append(i + 1)

    total = 0
    for start in range(n):
        if grid[start // W][start % W] != ".":
            continue
        stack = [(start, 1 << start, 0)]
        while stack:
            cell, visited, moves = stack.pop()
            if moves == K:
                total += 1
                continue
            for nxt in neighbors[cell]:
                bit = 1 << nxt
                if not (visited & bit) and grid[nxt // W][nxt % W] == ".":
                    stack.append((nxt, visited | bit, moves + 1))
    return total

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rotatable rectangles can exactly tile the grid."""
    if h <= 0 or w <= 0 or n < 0 or len(tiles) < n:
        return False
    pieces = tiles[:n]
    areas = [a * b for a, b in pieces]
    target = h * w
    if any(a <= 0 or b <= 0 for a, b in pieces):
        return False
    if sum(areas) < target:
        return False

    full = (1 << w) - 1
    initial = (0,) * h
    seen = set()

    def search(rows, used, filled):
        if filled == target:
            return True
        key = (rows, used)
        if key in seen:
            return False
        seen.add(key)

        # Every remaining piece is optional, but their total area must suffice.
        if sum(areas[i] for i in range(n) if not (used >> i) & 1) < target - filled:
            return False

        pos = -1
        for r in range(h):
            missing = full ^ rows[r]
            if missing:
                bit = missing & -missing
                c = bit.bit_length() - 1
                pos = (r, c)
                break
        if pos == -1:
            return True
        r, c = pos

        tried = set()
        for i, (a, b) in enumerate(pieces):
            if (used >> i) & 1:
                continue
            for dh, dw in {(a, b), (b, a)}:
                if (dh, dw) in tried:
                    continue
                tried.add((dh, dw))
                if r + dh > h or c + dw > w:
                    continue
                mask = ((1 << dw) - 1) << c
                if any(rows[rr] & mask for rr in range(r, r + dh)):
                    continue
                updated = list(rows)
                for rr in range(r, r + dh):
                    updated[rr] |= mask
                if search(tuple(updated), used | (1 << i), filled + dh * dw):
                    return True
        return False

    return search(initial, 0, 0)

MOD = 998244353


def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a, modulo MOD.

    A Polish sequence is the preorder degree sequence of an ordered rooted tree.
    """
    limit = 3 * n + 5
    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (limit + 1)
    inv_fact[limit] = pow(fact[limit], MOD - 2, MOD)
    for i in range(limit, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(top: int, bottom: int) -> int:
        if bottom < 0 or bottom > top:
            return 0
        return fact[top] * inv_fact[bottom] % MOD * inv_fact[top - bottom] % MOD

    def forest_count(roots: int, nodes: int) -> int:
        if roots <= 0:
            return 0
        return (comb(2 * nodes + roots - 1, nodes)
                - comb(2 * nodes + roots - 1, nodes - 1)) % MOD

    def forest_sum(lo: int, hi: int, nodes: int) -> int:
        """Sum forest_count(p, nodes) for p in [lo, hi]."""
        if lo > hi:
            return 0
        return (comb(2 * nodes + hi, nodes + 1)
                - comb(2 * nodes + lo - 1, nodes + 1)
                - comb(2 * nodes + hi, nodes)
                + comb(2 * nodes + lo - 1, nodes)) % MOD

    answer = 0
    pending = 1
    prefix_valid = True
    for i, bound in enumerate(a):
        remaining = n - i - 1
        # A smaller value x leaves pending+x-1 roots for the suffix.
        # At least one root must remain before the final element.
        lo = max(0, 2 - pending)
        hi = bound - 1
        if remaining == 0:
            # The final value must close the traversal exactly.
            needed = 1 - pending
            if lo <= needed <= hi:
                answer += 1
        elif lo <= hi:
            answer += forest_sum(pending + lo - 1, pending + hi - 1, remaining)

        if bound - 1 + pending <= 0:
            # Equal prefix reaches zero before the sequence ends, or fails to close.
            if not (remaining == 0 and bound - 1 + pending == 0):
                prefix_valid = False
                break
        pending += bound - 1
    if prefix_valid and pending == 0:
        answer += 1
    return answer % MOD

