def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the specified rectangle."""
    import math

    # Clip a convex polygon against an axis-aligned rectangle.
    def clipped_area(poly, x0, y0, x1, y1):
        pts = poly
        for axis, bound, keep_greater in (
            (0, x0, True), (0, x1, False),
            (1, y0, True), (1, y1, False),
        ):
            if not pts:
                return 0.0
            out = []
            prev = pts[-1]
            pv = prev[axis]
            pin = pv >= bound if keep_greater else pv <= bound
            for cur in pts:
                cv = cur[axis]
                cin = cv >= bound if keep_greater else cv <= bound
                if cin != pin:
                    t = (bound - pv) / (cv - pv)
                    cross = (prev[0] + t * (cur[0] - prev[0]),
                             prev[1] + t * (cur[1] - prev[1]))
                    out.append(cross)
                if cin:
                    out.append(cur)
                prev, pv, pin = cur, cv, cin
            pts = out
        if len(pts) < 3:
            return 0.0
        return abs(sum(pts[i][0] * pts[(i+1)%len(pts)][1] -
                       pts[(i+1)%len(pts)][0] * pts[i][1]
                       for i in range(len(pts))) / 2)

    # The coloring repeats after 4 units horizontally and 2 vertically.
    black = []
    for i in range(4):
        for j in range(2):
            x0, y0 = float(i), float(j)
            if (i + j) % 2:
                triangles = [
                    [(x0,y0),(x0+1,y0),(x0,y0+1)],
                    [(x0+1,y0),(x0+1,y0+1),(x0,y0+1)],
                ]
            else:
                triangles = [[(x0,y0),(x0+1,y0),(x0+1,y0+1),(x0,y0+1)]]
            for poly in triangles:
                sx = sum(p[0] for p in poly) / len(poly)
                sy = sum(p[1] for p in poly) / len(poly)
                parity = (abs(math.floor(sx)-math.floor(.5)) +
                          abs(math.floor(sy/2)-math.floor(.5/2)) +
                          abs(math.floor((sx+sy)/2)-math.floor(1/2))) & 1
                if parity == 0:
                    black.append(poly)

    def primitive(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        total = sum(clipped_area(p,0,0,4,2) for p in black)
        px = sum(clipped_area(p,0,0,rx,2) for p in black)
        py = sum(clipped_area(p,0,0,4,ry) for p in black)
        local = sum(clipped_area(p,0,0,rx,ry) for p in black)
        return qx*qy*total + qx*py + qy*px + local

    area = primitive(C,D)-primitive(A,D)-primitive(C,B)+primitive(A,B)
    return round(2*area)

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover the grid."""
    tiles = list(tiles[:n])
    target = h * w
    if sum(a * b for a, b in tiles) < target:
        return False

    full = (1 << target) - 1
    count = len(tiles)
    areas = [a * b for a, b in tiles]
    area_sum = [0] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        i = bit.bit_length() - 1
        area_sum[mask] = area_sum[mask ^ bit] + areas[i]

    # Cache valid placements for each tile and each possible top-left cell.
    placements = [[[] for _ in range(target)] for _ in range(count)]
    for i, (a, b) in enumerate(tiles):
        shapes = {(a, b), (b, a)}
        for rh, rw in shapes:
            if rh > h or rw > w:
                continue
            for r in range(h - rh + 1):
                for c in range(w - rw + 1):
                    bits = 0
                    for rr in range(r, r + rh):
                        start = rr * w + c
                        bits |= ((1 << rw) - 1) << start
                    placements[i][r * w + c].append(bits)

    failed = set()

    def search(occupied: int, available: int) -> bool:
        if occupied == full:
            return True
        remaining = target - occupied.bit_count()
        if area_sum[available] < remaining:
            return False
        state = (occupied, available)
        if state in failed:
            return False

        # The first uncovered cell must be the top-left corner of the next
        # rectangle: any rectangle covering it from above or the left would
        # overlap an already covered cell.
        first_bit = (full ^ occupied) & -(full ^ occupied)
        pos = first_bit.bit_length() - 1
        for i in range(count):
            bit = 1 << i
            if not (available & bit):
                continue
            # Identical tiles are interchangeable; try only one at each state.
            duplicate_seen = False
            for j in range(i):
                if (available & (1 << j)) and tiles[j] == tiles[i]:
                    duplicate_seen = True
                    break
            if duplicate_seen:
                continue
            next_available = available ^ bit
            for placement in placements[i][pos]:
                if not (occupied & placement) and search(occupied | placement, next_available):
                    return True
        failed.add(state)
        return False

    return search(0, (1 << count) - 1)

MOD = 998244353


def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a, modulo 998244353."""
    # Binomial coefficients up to 2n are enough for the forest completion counts.
    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (2 * n + 1)
    inv_fact[2 * n] = pow(fact[2 * n], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or top < bottom or top < 0:
            return 0
        return fact[top] * inv_fact[bottom] % MOD * inv_fact[top - bottom] % MOD

    def sum_forests(r: int, low: int, high: int) -> int:
        """Sum over t=low..high of forests of t ordered trees on r nodes."""
        if r == 0:
            return int(low <= 0 <= high)
        if low < 1:
            low = 1
        if high > r:
            high = r
        if low > high:
            return 0
        # F(t,r) = t/r * C(2r-t-1,r-1). Summing after setting
        # k=2r-t-1 telescopes to C(k,r-1)-C(k,r).
        k_low = 2 * r - high - 1
        k_high = 2 * r - low - 1
        return (choose(k_high + 1, r) - choose(k_low, r)
                - choose(k_high + 1, r + 1) + choose(k_low, r + 1)) % MOD

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        remaining = n - i - 1

        # Count valid sequences whose first difference here is smaller than a[i].
        low = max(1, slots - 1)
        high = min(remaining, slots + bound - 2)
        answer += sum_forests(remaining, low, high)
        answer %= MOD

        # Continue along the equal prefix only if it can still be completed.
        slots += bound - 1
        if remaining == 0:
            if slots == 0:
                answer = (answer + 1) % MOD
        elif slots < 1 or slots > remaining:
            break

    return answer

