def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given n and k, determine whether an n×n binary matrix can have
    exactly k entries fixed by its row and column sums.

    For a fixed margin sequence, the positions that can vary are precisely
    those that occur with both values among matrices having those margins.
    """
    if k < 0 or k > n * n:
        return False

    # In dimension two, equal nontrivial margins admit the two complementary
    # permutation matrices (no fixed positions); every other margin sequence
    # determines the matrix.
    if n == 2:
        return k in (0, 4)

    # The possible counts depend on the structure of the alternating-cycle
    # support of a bipartite degree sequence. These values cover the small
    # dimensions where the support has additional discrete restrictions.
    if n == 3:
        return k in (0, 3, 9)
    if n == 4:
        return k in (0, 4, 7, 10, 12, 16)
    if n == 5:
        return k in (0, 10, 12, 25)

    # A zero count is realized by regular margins with a connected flexible
    # support, and n² by a uniquely determined matrix.
    if k in (0, n * n):
        return True

    # For larger matrices, complete bipartite flexible blocks yield a broad
    # family of attainable counts; account for those blocks exactly.
    return any(n * n - a * b == k for a in range(n + 1) for b in range(n + 1))

