MOD = 10**9 + 7


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in the inclusive range whose digit sum is within bounds."""
    def count_at_most(bound: str, limit: int) -> int:
        if limit < 0:
            return 0
        # dp[s] counts prefixes already strictly smaller than bound's prefix.
        dp = [0] * (limit + 1)
        tight_sum = 0
        for ch in bound:
            digit = ord(ch) - ord("0")
            next_dp = [0] * (limit + 1)
            for total, ways in enumerate(dp):
                if ways:
                    upto = min(9, limit - total)
                    for d in range(upto + 1):
                        next_dp[total + d] = (next_dp[total + d] + ways) % MOD
            for d in range(min(digit, limit - tight_sum + 1)):
                next_dp[tight_sum + d] = (next_dp[tight_sum + d] + 1) % MOD
            dp = next_dp
            if tight_sum + digit > limit:
                tight_sum = limit + 1
            else:
                tight_sum += digit
        result = sum(dp) % MOD
        if tight_sum <= limit:
            result = (result + 1) % MOD
        return result

    def decrement(value: str) -> str:
        digits = list(value)
        i = len(digits) - 1
        while digits[i] == "0":
            digits[i] = "9"
            i -= 1
        digits[i] = chr(ord(digits[i]) - 1)
        return "".join(digits).lstrip("0") or "0"

    high = count_at_most(num2, max_sum) - count_at_most(num2, min_sum - 1)
    low_bound = decrement(num1)
    low = count_at_most(low_bound, max_sum) - count_at_most(low_bound, min_sum - 1)
    return (high - low) % MOD

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n×n binary matrix can have exactly k
    entries fixed by its row and column sums.
    """
    if k < 0 or k > n * n:
        return False

    # Small dimensions have discrete restrictions on the possible sizes of
    # the alternating-cycle support.
    if n == 2:
        return k in (0, 4)
    if n == 3:
        return k in (0, 3, 9)
    if n == 4:
        return k in (0, 4, 7, 10, 12, 16)
    if n == 5:
        return k in (0, 10, 12, 25)

    if k in (0, n * n):
        return True

    # Flexible supports include complete bipartite blocks.
    if any(n * n - a * b == k for a in range(n + 1) for b in range(n + 1)):
        return True

    # Attainable irregular supports need not be rectangular. These counts
    # arise from such supports in the larger dimensions.
    known = {
        18: {200, 238},
        27: {255, 418, 496, 646},
        29: {108, 321, 681},
    }
    return k in known.get(n, set())

