def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """ Given two strings s and t of length n consisting of 'B' and 'W' characters,
    determine the minimum number of operations needed to transform the initial configuration s
    into the target configuration t.

    Initially, there are n stones placed in cells 1 to n according to string s,
    where 'W' represents a white stone and 'B' represents a black stone.
    There are also two empty cells at positions n+1 and n+2.

    In one operation, you can:
    - Choose two adjacent cells that both contain stones
    - Move these two stones to the two empty cells while preserving their order

    Return the minimum number of operations needed to achieve configuration t,
    or -1 if it's impossible.
    """
    if len(s) != n or len(t) != n or s.count("B") != t.count("B"):
        return -1

    start = s + ".."
    goal = t + ".."
    if start == goal:
        return 0

    def neighbors(state):
        holes = [i for i, ch in enumerate(state) if ch == "."]
        left_hole, right_hole = holes
        for i in range(n + 1):
            first, second = state[i], state[i + 1]
            if first == "." or second == ".":
                continue
            chars = list(state)
            chars[i] = chars[i + 1] = "."
            chars[left_hole] = first
            chars[right_hole] = second
            yield "".join(chars)

    from_start = {start: 0}
    from_goal = {goal: 0}
    frontier_start = {start}
    frontier_goal = {goal}
    depth_start = depth_goal = 0

    while frontier_start and frontier_goal:
        if len(frontier_start) <= len(frontier_goal):
            current, own, other = frontier_start, from_start, from_goal
            next_frontier = set()
            for state in current:
                next_depth = own[state] + 1
                for nxt in neighbors(state):
                    if nxt in own:
                        continue
                    if nxt in other:
                        return next_depth + other[nxt]
                    own[nxt] = next_depth
                    next_frontier.add(nxt)
            frontier_start = next_frontier
            depth_start += 1
        else:
            current, own, other = frontier_goal, from_goal, from_start
            next_frontier = set()
            for state in current:
                next_depth = own[state] + 1
                for nxt in neighbors(state):
                    if nxt in own:
                        continue
                    if nxt in other:
                        return next_depth + other[nxt]
                    own[nxt] = next_depth
                    next_frontier.add(nxt)
            frontier_goal = next_frontier
            depth_goal += 1

    return -1

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum scores of all good sequences modulo 998244353."""
    mod = 998244353

    # For each prime, record the exponent of that prime on every edge.
    exponents: dict[int, list[int]] = {}
    for value_index, value in enumerate(a):
        remaining = value
        divisor = 2
        while divisor * divisor <= remaining:
            if remaining % divisor == 0:
                exponent = 0
                while remaining % divisor == 0:
                    remaining //= divisor
                    exponent += 1
                exponents.setdefault(divisor, [0] * (n - 1))[value_index] = exponent
            divisor += 1 if divisor == 2 else 2
        if remaining > 1:
            exponents.setdefault(remaining, [0] * (n - 1))[value_index] = 1

    answer = 1
    for prime, steps in exponents.items():
        total_down = sum(steps)
        # After shifting a path so its minimum is zero, its initial height is
        # at most the total possible downward movement.
        max_height = 2 * total_down
        weights = [pow(prime, height, mod) for height in range(max_height + 1)]

        # Sum all nonnegative paths whose initial height is at most total_down,
        # excluding paths that stay strictly positive. Shifting a strictly
        # positive path down by one multiplies its score by prime**n.
        dp = [0] * (max_height + 1)
        shifted_weight = pow(prime, n, mod)
        for height in range(total_down):
            dp[height] = (1 - shifted_weight) % mod
        dp[total_down] = 1

        for step in steps:
            if step == 0:
                for height, count in enumerate(dp):
                    if count:
                        dp[height] = count * weights[height] % mod
            else:
                next_dp = [0] * (max_height + 1)
                for height, count in enumerate(dp):
                    if not count:
                        continue
                    lower = height - step
                    if lower >= 0:
                        next_dp[lower] = (next_dp[lower] + count * weights[lower]) % mod
                    upper = height + step
                    if upper <= max_height:
                        next_dp[upper] = (next_dp[upper] + count * weights[upper]) % mod
                dp = next_dp

        factor_sum = sum(dp) % mod
        answer = answer * factor_sum % mod

    return answer

