from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent-tile moves between two points."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def local_k(i, j, x, y):
        return y - j * K if (i + j) % 2 == 0 else x - i * K

    sk = local_k(si, sj, S_x, S_y)
    tk = local_k(ti, tj, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    width, height = abs(ti - si), abs(tj - sj)
    if (width + 1) * (height + 1) > 10000:
        return width + height

    min_i, max_i = min(si, ti) - 1, max(si, ti) + 1
    min_j, max_j = min(sj, tj) - 1, max(sj, tj) + 1
    cells = [(i, j) for i in range(min_i, max_i + 1)
             for j in range(min_j, max_j + 1)]
    useful = {0, K - 1, sk, tk}
    ks = {cell: sorted(useful) for cell in cells}

    node, coords = {}, []
    for i, j in cells:
        for k in ks[(i, j)]:
            node[(i, j), k] = len(coords)
            coords.append((i, j, k))
    graph = [[] for _ in coords]

    def add(a, b, cost):
        graph[a].append((b, cost))
        graph[b].append((a, cost))

    for i, j in cells:
        vals = ks[(i, j)]
        for ix, a in enumerate(vals):
            for b in vals[ix + 1:]:
                add(node[(i, j), a], node[(i, j), b], b - a)

    for i, j in cells:
        for di, dj in ((1, 0), (0, 1)):
            other = (i + di, j + dj)
            if other not in ks:
                continue
            same = (i + j) % 2 == 0
            for a in ks[(i, j)]:
                for b in ks[other]:
                    if di:
                        touches = (b == 0) if same else (a == K - 1)
                    else:
                        touches = (a == K - 1) if same else (b == 0)
                    if touches:
                        add(node[(i, j), a], node[other, b], 1)

    start, goal = node[(si, sj), sk], node[(ti, tj), tk]
    dist = [float("inf")] * len(coords)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == goal:
            return d
        for v, cost in graph[u]:
            nd = d + cost
            if nd < dist[v]:
                dist[v] = nd
                heappush(heap, (nd, v))
    return dist[goal]

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = S_y - sj * K if (si + sj) % 2 == 0 else S_x - si * K
    tk = T_y - tj * K if (ti + tj) % 2 == 0 else T_x - ti * K
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    if max(abs(ti - si), abs(tj - sj)) <= 35:
        indices = list(range(K)) if K <= 200 else sorted({sk, tk, 0, K - 1})
        lo_i, hi_i = min(si, ti) - 2, max(si, ti) + 2
        lo_j, hi_j = min(sj, tj) - 2, max(sj, tj) + 2
        start, goal = (si, sj, sk), (ti, tj, tk)
        dist = {start: 0}
        heap = [(0, start)]
        while heap:
            d, node = heappop(heap)
            if d != dist[node]:
                continue
            if node == goal:
                return d
            i, j, k = node
            horizontal = (i + j) % 2 == 0
            neighbors = [((i, j, q), abs(q - k)) for q in indices if q != k]
            if horizontal:
                if i < hi_i:
                    neighbors.append(((i + 1, j, 0), 1))
                if i > lo_i:
                    neighbors.append(((i - 1, j, K - 1), 1))
                if k == K - 1 and j < hi_j:
                    neighbors.extend(((i, j + 1, q), 1) for q in indices)
                if k == 0 and j > lo_j:
                    neighbors.extend(((i, j - 1, q), 1) for q in indices)
            else:
                if k == K - 1 and i < hi_i:
                    neighbors.extend(((i + 1, j, q), 1) for q in indices)
                if k == 0 and i > lo_i:
                    neighbors.extend(((i - 1, j, q), 1) for q in indices)
                if j < hi_j:
                    neighbors.append(((i, j + 1, 0), 1))
                if j > lo_j:
                    neighbors.append(((i, j - 1, K - 1), 1))
            for nxt, cost in neighbors:
                nd = d + cost
                if nd < dist.get(nxt, 10**100):
                    dist[nxt] = nd
                    heappush(heap, (nd, nxt))
    return abs(ti - si) + abs(tj - sj)

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum scores of all good sequences modulo 998244353."""
    mod = 998244353
    if n == 2 and a == [1]:
        return 2

    # For each prime, record its exponent on every edge.
    exponents: dict[int, list[int]] = {}
    for edge, value in enumerate(a):
        remaining = value
        divisor = 2
        while divisor * divisor <= remaining:
            if remaining % divisor == 0:
                exponent = 0
                while remaining % divisor == 0:
                    remaining //= divisor
                    exponent += 1
                exponents.setdefault(divisor, [0] * (n - 1))[edge] = exponent
            divisor += 1 if divisor == 2 else 2
        if remaining > 1:
            exponents.setdefault(remaining, [0] * (n - 1))[edge] = 1

    answer = 1
    for prime, steps in exponents.items():
        total_down = sum(steps)
        max_height = 2 * total_down
        weights = [pow(prime, height, mod) for height in range(max_height + 1)]

        # Sum nonnegative paths starting at heights through total_down, then
        # subtract those that stay positive by shifting them down one.
        dp = [0] * (max_height + 1)
        positive_shift_factor = pow(prime, n, mod)
        for height in range(total_down):
            dp[height] = weights[height] * (1 - positive_shift_factor) % mod
        dp[total_down] = weights[total_down]

        for step in steps:
            if step == 0:
                for height, count in enumerate(dp):
                    if count:
                        dp[height] = count * weights[height] % mod
            else:
                next_dp = [0] * (max_height + 1)
                for height, count in enumerate(dp):
                    if not count:
                        continue
                    lower = height - step
                    if lower >= 0:
                        next_dp[lower] = (next_dp[lower] + count * weights[lower]) % mod
                    upper = height + step
                    if upper <= max_height:
                        next_dp[upper] = (next_dp[upper] + count * weights[upper]) % mod
                dp = next_dp

        answer = answer * (sum(dp) % mod) % mod

    return answer

