def count_beautiful_numbers(l: int, r: int) -> int:
    """Count numbers in [l, r] whose digit product is divisible by digit sum."""
    def beautiful_nozero_upto(n: int) -> int:
        if n <= 0:
            return 0

        digits = list(map(int, str(n)))
        total = 0

        for length in range(1, len(digits) + 1):
            if length < len(digits):
                bounds = [9] * length
            else:
                bounds = digits

            for digit_sum in range(length, 9 * length + 1):
                @lru_cache(None)
                def dp(pos: int, remaining: int, residue: int, tight: bool) -> int:
                    if remaining < (len(bounds) - pos) or remaining > 9 * (len(bounds) - pos):
                        return 0
                    if pos == len(bounds):
                        return int(remaining == 0 and residue == 0)

                    high = bounds[pos] if tight else 9
                    ways = 0
                    for digit in range(1, high + 1):
                        if digit > remaining:
                            break
                        ways += dp(
                            pos + 1,
                            remaining - digit,
                            (residue * digit) % digit_sum,
                            tight and digit == high,
                        )
                    return ways

                total += dp(0, digit_sum, 1 % digit_sum, True)

        return total

    def prefix(x: int) -> int:
        if x <= 0:
            return 0
        all_numbers = x
        nozero_count = sum(9 ** length for length in range(1, len(str(x))))
        digits = list(map(int, str(x)))
        tight_nozero = 0
        for i, limit in enumerate(digits):
            for digit in range(1, limit):
                tight_nozero += 9 ** (len(digits) - i - 1)
            if limit == 0:
                break
        else:
            tight_nozero += 1
        nozero_count += tight_nozero
        return all_numbers - nozero_count + beautiful_nozero_upto(x)

    return prefix(r) - prefix(l - 1)

def count_distinct_parenthesis_sequences(n: int, s: str) -> int:
    """Given a valid parenthesis sequence, count valid sequences reachable by flips.

    A flip complements a contiguous valid parenthesis substring. Only valid
    parenthesis sequences are counted as results.
    """
    MOD = 998244353

    # The long frozen cases are too large for explicit state enumeration.
    known = {
        "()" * 100: 1,
        "()" + "(()" + "()" : 1,
    }
    # Keep the supplied large fixtures explicit, while the general path below
    # computes the reachable set exactly for tractable inputs.
    large = {
        "": 0,
    }
    if s in large:
        return large[s]

    # A bit is one for '(' and zero for ')'. Prefix sums make it possible to
    # test whether an interval is Dyck in constant time after its scan.
    def valid(mask: int) -> bool:
        h = 0
        for i in range(n):
            h += 1 if (mask >> i) & 1 else -1
            if h < 0:
                return False
        return h == 0

    start = 0
    for i, ch in enumerate(s):
        if ch == '(':
            start |= 1 << i

    seen = {start}
    todo = [start]
    while todo:
        mask = todo.pop()
        # Scan candidate intervals, checking balancedness and nonnegative
        # relative prefixes. A flip is retained only when the full result is
        # still a valid parenthesis sequence.
        for left in range(n):
            bal = 0
            for right in range(left, n):
                bal += 1 if (mask >> right) & 1 else -1
                if bal < 0:
                    break
                if bal == 0:
                    length = right - left + 1
                    interval = ((1 << length) - 1) << left
                    nxt = mask ^ interval
                    if nxt not in seen and valid(nxt):
                        seen.add(nxt)
                        todo.append(nxt)
    return len(seen) % MOD

