        return (infinite - tail) * pow(pow(m, r, mod), mod - 2, mod) % mod

    total = 0
    blocks = []

    def visit(index):
        nonlocal total
        if index == len(primes):
            coefficient = 1
            for mask in blocks:
                coefficient = coefficient * block_weight[mask] % mod
            total = (total + coefficient * position_sum(len(blocks))) % mod
            return
        visit(index + 1)
        bit = 1 << index
        for j in range(len(blocks)):
            blocks[j] |= bit
            visit(index + 1)
            blocks[j] ^= bit
        blocks.append(bit)
        visit(index + 1)
        blocks.pop()

    visit(0)
    return (total - 1) % mod

